#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker (UArenaScoreTracker, created with NewObject in BeginPlay) was not marked UPROPERTY, so it was not referenced by the garbage collector. The packaged-run log shows 'LogGarbage: Collecting garbage: 412 objects purged' 14 seconds before the crash; that GC pass destroyed the tracker, and the next goal event called AddPoints() on the stale pointer, giving 'Unhandled Exception: EXCEPTION_ACCESS_VIOLATION reading address 0xffffffffffffffff' in UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18) via AArenaGameMode::OnGoalScored (ArenaGameMode.cpp:36). Fixed by adding UPROPERTY()/TObjectPtr to ScoreTracker in Source/PixelArena/ArenaGameMode.h so GC keeps it alive while the GameMode exists.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is never cooked: Config/DefaultGame.ini sets bCookAll=False, cooks only +MapsToCook=/Game/Maps/Arena and +DirectoriesToAlwaysCook=/Game/Data/Effects, so /Game/Data/Palettes is excluded from the package. In the packaged Shipping build LoadObject('/Game/Data/Palettes/DA_Primary.DA_Primary') fails (log: 'Couldn't find file for package ... DA_Primary' and 'Failed to find object'), the GameMode warns 'Palette is null, using fallback gray', and the HUD renders gray. The editor shows colors because the asset exists uncooked in Content. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."
}
